import{_ as n,o as e,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const l=JSON.parse('{"title":"Caption dùng ngữ cảnh trend từ Neo4j và ChromaDB","description":"","frontmatter":{},"headers":[],"relativePath":"feature/caption-trend-retrieval/spec.md","filePath":"feature/caption-trend-retrieval/spec.md"}'),r={name:"feature/caption-trend-retrieval/spec.md"};function c(h,t,d,o,g,u){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="caption-dung-ngu-canh-trend-tu-neo4j-va-chromadb" tabindex="-1">Caption dùng ngữ cảnh trend từ Neo4j và ChromaDB <a class="header-anchor" href="#caption-dung-ngu-canh-trend-tu-neo4j-va-chromadb" aria-label="Permalink to &quot;Caption dùng ngữ cảnh trend từ Neo4j và ChromaDB&quot;">​</a></h1><p>Trạng thái: đề xuất để review, chưa được phép triển khai code. Ngày 2026-11-03.</p><h2 id="muc-tieu-va-hien-trang" tabindex="-1">Mục tiêu và hiện trạng <a class="header-anchor" href="#muc-tieu-va-hien-trang" aria-label="Permalink to &quot;Mục tiêu và hiện trạng&quot;">​</a></h2><p>Creator chọn một trend và tạo ba caption có ngữ cảnh thật, phù hợp brand/task/platform. Giữ luồng gen caption thường, refine/adapt, moderation và credit hiện có.</p><p>Đối chiếu repo AI: <code>content.py</code> tra <code>trend_id</code> qua <code>trend_fit/store.py</code> (event từ Redis, moment/format từ nguồn hiện hữu). <code>caption_service.knowledge_chunks</code> chỉ truy vấn tài liệu brand trong collection <code>brandhub_rag</code>, lọc <code>clientId</code>; chưa truy vấn <code>social_trend_chunks</code> cho caption. Neo4j có Trend/CrawledPost/Entity và liên kết BELONGS_TO/MENTIONS/ASSOCIATED_WITH. Chroma trend metadata có trendId, postId, runId, sourceUrl, platform và thời gian. Các field tồn tại trong code không đảm bảo dữ liệu cũ đã đầy đủ; cần audit trước.</p><h2 id="ba-va-acceptance-criteria" tabindex="-1">BA và acceptance criteria <a class="header-anchor" href="#ba-va-acceptance-criteria" aria-label="Permalink to &quot;BA và acceptance criteria&quot;">​</a></h2><table tabindex="0"><thead><tr><th>BA</th><th>Phạm vi</th><th>Tiêu chí</th></tr></thead><tbody><tr><td>BA-01</td><td>P0: chọn cách dùng trend</td><td>Giữ gen thường và dùng trend đã chọn. Chỉ khi có lựa chọn trend mới truy xuất trend; không tự gắn trend khác.</td></tr><tr><td>BA-02</td><td>P0: ngữ cảnh Neo4j</td><td>Tra trendId chính xác; đọc tên, ngày, score và các nguồn/thực thể liên quan có bằng chứng. Không bắt buộc post có Entity mới đủ điều kiện, không mở rộng graph vô hạn.</td></tr><tr><td>BA-03</td><td>P0: ngữ cảnh Chroma</td><td>Tìm nội dung theo topic + brand/task + trend được chọn; prefilter trendId và runId hợp lệ, loại trùng post/chunk. Không query toàn bộ rồi nhận trend không liên quan.</td></tr><tr><td>BA-04</td><td>P0: chất lượng dữ liệu</td><td>Chỉ dùng nguồn của run đã công bố; loại test/replay namespace, run đang chạy/failed/interrupted và batch failed. Run partial chỉ dùng phần đã publish và thành công, hiển thị nhãn thiếu dữ liệu.</td></tr><tr><td>BA-05</td><td>P0: thời gian</td><td>Mặc định trend sự kiện trong 7 ngày theo Asia/Ho_Chi_Minh; không gọi một trend cũ là đang hot. Moment/format giữ quy tắc hiệu lực hiện tại, không ép sang graph/chunk.</td></tr><tr><td>BA-06</td><td>P0: phù hợp thương hiệu</td><td>Giữ brand voice, mục tiêu, audience, platform, kỹ thuật trend-fit và ba loại HOOK_DRIVEN/STORYTELLING/DIRECT_CTA. Không ép mọi thương hiệu vào sự kiện nhạy cảm.</td></tr><tr><td>BA-07</td><td>P0: phân biệt nguồn</td><td>Giá, ưu đãi và cam kết sản phẩm chỉ lấy từ dữ liệu brand đã xác nhận. Bài crawl là tham khảo xã hội, không mặc định là sự thật đã kiểm chứng. Nội dung nguồn không được trở thành chỉ dẫn cho model.</td></tr><tr><td>BA-08</td><td>P0: xem bằng chứng</td><td>Trả metadata nguồn để creator xem trend, thời gian, link nguồn và trạng thái đầy đủ/thiếu dữ liệu; phần này nằm ngoài caption. Không nói nguồn được dùng chỉ vì đã retrieve nếu không có bằng chứng cấp từng câu.</td></tr><tr><td>BA-09</td><td>P0: thiếu dữ liệu/sự cố</td><td>Trả trạng thái có cấu trúc khi trend hết hạn, không có nguồn phù hợp, thiếu Chroma hoặc DB timeout. Không thay trend âm thầm. Với trend không khả dụng, creator chọn lại hoặc chuyển rõ ràng sang gen thường.</td></tr><tr><td>BA-10</td><td>P0: bảo toàn thao tác sau gen</td><td>Lưu context snapshot/provenance của generation; refine/adapt tái dùng ngữ cảnh đã chọn, không tự chuyển sang trend mới khi dữ liệu cập nhật. Giữ moderation và credit/idempotency hiện có.</td></tr><tr><td>BA-11</td><td>P0: phân quyền</td><td>Business xác thực actor/workspace rồi truyền client_id nội bộ. Brand KB luôn lọc tenant; trend công khai tách khỏi dữ liệu brand/private namespace. Không nhận Cypher, filter tùy ý hoặc nguồn secret từ frontend.</td></tr><tr><td>BA-12</td><td>P0: vận hành và đánh giá</td><td>Có giới hạn context, timeout, concurrency, telemetry; không crawl trong request caption, không thêm model/reranker nặng trong bản đầu. Đánh giá liên quan, độ mới, grounding, latency và RAM trước rollout.</td></tr><tr><td>BA-13</td><td>P1: tự đề xuất trend</td><td>Khi creator bật chế độ tự tìm, trả tối đa ba trend phù hợp để chọn/xác nhận. Không âm thầm bắt trend; score kết hợp ngữ nghĩa, độ mới và brand-fit, cần hiệu chỉnh bằng bộ đánh giá.</td></tr></tbody></table><h2 id="ui-ux-va-i18n" tabindex="-1">UI/UX và i18n <a class="header-anchor" href="#ui-ux-va-i18n" aria-label="Permalink to &quot;UI/UX và i18n&quot;">​</a></h2><p>Tái sử dụng trang gen caption và picker hiện có; hiển thị ngắn gọn “Ngữ cảnh trend” cùng nguồn tham khảo, trạng thái thiếu dữ liệu và hành động chọn lại/gen thường. Không đưa tên database hoặc query vào luồng creator. Hỗ trợ vi/en song song, dự kiến namespace <code>ai.caption.trendContext.*</code>; chốt key sau audit UI. Dùng token/theme hiện có; kiểm tra light/dark, mobile và bàn phím. Không thêm account hoặc trang admin mới.</p><h2 id="contract-du-kien-tuong-thich" tabindex="-1">Contract dự kiến, tương thích <a class="header-anchor" href="#contract-du-kien-tuong-thich" aria-label="Permalink to &quot;Contract dự kiến, tương thích&quot;">​</a></h2><p>Giữ endpoint <code>/api/v1/ai/content/captions/variants</code> và endpoint public đang được Business cung cấp; xác minh path đầy đủ khi triển khai. Tái dùng <code>trend_id</code>; không bắt caller cũ đổi payload khi gen thường. Response thêm trường optional cho context/provenance, không đổi caption text/hashtags contract hiện hữu. Business phải forward và persist các field mới thay vì làm mất metadata qua record DTO.</p><p>Context dự kiến: status (<code>used</code>, <code>insufficient</code>, <code>unavailable</code>, <code>not_requested</code>), trendId, publication/run revision, window/asOf, source references, selection policy version. Reference tối thiểu gồm postId, platform, sourceUrl, publishedAt/crawledAt, chunkId và loại nguồn. Nội dung prompt đầy đủ và cookie/token không trả ra response/log.</p><h2 id="ngoai-pham-vi" tabindex="-1">Ngoài phạm vi <a class="header-anchor" href="#ngoai-pham-vi" aria-label="Permalink to &quot;Ngoài phạm vi&quot;">​</a></h2><p>Không thay model/provider/credit pricing, thuật toán chấm điểm trend, quy trình crawler hay sửa code production. Không sao chép nguyên bài của nguồn vào caption. Chưa triển khai code, backfill hoặc thay đổi schema trước review kế hoạch.</p>',14)])])}const s=n(r,[["render",c]]);export{l as __pageData,s as default};
